%[text] # verifying self-shadowing function
clc
clear
close all

const = orbitConst %[output:3fe9d069]
%%
%[text] ## load object
sat = readSC('boxWing4.obj'); %[output:249f52b2]
size(sat.vertices) % nVertices %[output:2073431b]
size(sat.faces) % nFaces %[output:4f4ce173]

showSC(sat) %[output:6bab99d3]
%%
%[text] ## parameters
sunDir = [0.8 -0.3 0.62]; % nominal sun vector
sunDir = sunDir./norm(sunDir);
sunDist = const.AU * 10^3; % m
%[text] ### codegen for mex
%[text] mex化する関数に `%#codegen` をつける
%[text] つけたあとに出てくるエラーを解消する
%[text] `codegen (filename).(拡張子) -args {}`
%[text] **-argsの中身の型はmex化関数を呼び出すときの引数の型と同じにする**
%[text] `(filename)_mex.mexmaca64`ファイルと`codegen`フォルダが作成される
%[text] 使い方は普通の関数と同じ
%[text] `(filename)_mex(引数)`
tmpsun = ones(1,3,1);
codegen -report selfShadow.mlx -args {sat, tmpsun} % 三角facetと四角facetに応じて作り直さないとダメ

tic
sat = selfShadow(sat, sunDir); % calc self shadowing
toc %[output:78f79f50]

tic
satMex = selfShadow_mex(sat, sunDir); % calc self shadowing %[output:4fcf7b3f]
toc
%%
%[text] ## show figures
%[text] for non-mex function
figure
hold on
cb = colorbar;
colormap bone
% caxis([0 1e-7])

satFig = patch('Faces',sat.faces,'Vertices',sat.vertices);
set(satFig, 'FaceColor', 'b');
set(satFig, 'FaceLighting','phong','EdgeLighting','phong');
set(satFig, 'FaceVertexCData', sat.shadowFlag, 'FaceColor', 'flat')

axis equal
grid on
xlabel('X'),ylabel('Y'),zlabel('Z')
view(130,30);
quiver3(0, 0, 0, 3*sunDir(1),3*sunDir(2),3*sunDir(3) ,'r') % show sun direction
%[text] for mex function
figure
hold on
cb = colorbar;
colormap bone
% caxis([0 1e-7])

satFig = patch('Faces',satMex.faces,'Vertices',satMex.vertices);
set(satFig, 'FaceColor', 'b');
set(satFig, 'FaceLighting','phong','EdgeLighting','phong');
set(satFig, 'FaceVertexCData', satMex.shadowFlag, 'FaceColor', 'flat')

axis equal
grid on
xlabel('X'),ylabel('Y'),zlabel('Z')
view(130,30);
quiver3(0, 0, 0, 3*sunDir(1),3*sunDir(2),3*sunDir(3) ,'r') % show sun direction
%%
%[text] ## calculation for variable attitude
%[text] 
% atti = 0:10:80; % attitude angle , deg
% for i = 1:length(atti) DCM = ZYX2DCM(deg2rad(atti(i)), 0.0, 0.0)'; % NOTE: vector rotation sun_var = DCM * sun;
%     sat = SRP_LPS_obj(sat, sun_var, sun_dist); % SRP calculation
